diff --git a/tests/unit/data/canvas-chat.test.ts b/tests/unit/data/canvas-chat.test.ts
new file mode 100644
index 0000000..8e49791
--- /dev/null
+++ b/tests/unit/data/canvas-chat.test.ts
@@ -0,0 +1,213 @@
+import { describe, it, expect, beforeEach, vi } from 'vitest';
+import { UserRole } from '@prisma/client';
+
+import prisma from '@/lib/prisma';
+import { currentUser } from '@/lib/auth';
+import { saveMessages } from '@/data/canvas-chat';
+import type { User } from '@/types/next-auth';
+
+// Track createMany calls to inspect the data passed
+const mockCreateMany = vi.fn();
+const mockUpdate = vi.fn();
+const mockFindMany = vi.fn();
+
+vi.mock('@/lib/prisma', () => ({
+  default: {
+    canvasChatConversation: {
+      findFirst: vi.fn()
+    },
+    $transaction: vi.fn()
+  }
+}));
+
+vi.mock('@/lib/auth', () => ({
+  currentUser: vi.fn()
+}));
+
+const mockUser: User = {
+  id: 'user-id',
+  name: 'Test User',
+  email: 'test@example.com',
+  role: UserRole.USER,
+  isTwoFactorEnabled: false,
+  isOAuth: false,
+  membership: 'FREE'
+};
+
+describe('saveMessages', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+
+    vi.mocked(currentUser).mockResolvedValue(mockUser);
+
+    // Mock findFirst to return a valid conversation
+    vi.mocked(prisma.canvasChatConversation.findFirst).mockResolvedValue({
+      id: 'conv-1',
+      canvasDraftId: 'draft-1',
+      userId: 'user-id',
+      createdAt: new Date(),
+      updatedAt: new Date(),
+      deletedAt: null,
+      deletedBy: null
+    } as never);
+
+    // Mock $transaction to execute the callback with a mock tx
+    mockCreateMany.mockResolvedValue({ count: 0 });
+    mockUpdate.mockResolvedValue({});
+    mockFindMany.mockResolvedValue([]);
+
+    vi.mocked(prisma.$transaction).mockImplementation(async (cb: unknown) => {
+      if (typeof cb === 'function') {
+        const tx = {
+          canvasChatMessage: {
+            findMany: mockFindMany,
+            createMany: mockCreateMany,
+            update: mockUpdate
+          },
+          canvasChatConversation: {
+            update: vi.fn().mockResolvedValue({})
+          }
+        };
+        return cb(tx);
+      }
+    });
+  });
+
+  it('should pass client-provided createdAt timestamps to createMany for new messages', async () => {
+    const userTime = new Date('2025-01-01T10:00:00.000Z');
+    const assistantTime = new Date('2025-01-01T10:00:05.000Z');
+
+    const messages = [
+      {
+        id: 'msg-1',
+        role: 'user',
+        content: 'Hello',
+        createdAt: userTime
+      },
+      {
+        id: 'msg-2',
+        role: 'assistant',
+        content: 'Hi there!',
+        createdAt: assistantTime
+      }
+    ];
+
+    // No existing messages
+    mockFindMany.mockResolvedValue([]);
+
+    const result = await saveMessages('conv-1', 'draft-1', messages);
+
+    expect(result.success).toBe(true);
+    expect(mockCreateMany).toHaveBeenCalledTimes(1);
+
+    const createManyData = mockCreateMany.mock.calls[0][0].data;
+    expect(createManyData).toHaveLength(2);
+    expect(createManyData[0].createdAt).toEqual(userTime);
+    expect(createManyData[1].createdAt).toEqual(assistantTime);
+  });
+
+  it('should preserve message order via createdAt — user message before assistant message', async () => {
+    const userTime = new Date('2025-01-01T10:00:00.000Z');
+    const assistantTime = new Date('2025-01-01T10:00:03.000Z');
+    const userTime2 = new Date('2025-01-01T10:00:10.000Z');
+    const assistantTime2 = new Date('2025-01-01T10:00:15.000Z');
+
+    const messages = [
+      { id: 'msg-1', role: 'user', content: 'First', createdAt: userTime },
+      {
+        id: 'msg-2',
+        role: 'assistant',
+        content: 'Reply 1',
+        createdAt: assistantTime
+      },
+      {
+        id: 'msg-3',
+        role: 'user',
+        content: 'Second',
+        createdAt: userTime2
+      },
+      {
+        id: 'msg-4',
+        role: 'assistant',
+        content: 'Reply 2',
+        createdAt: assistantTime2
+      }
+    ];
+
+    mockFindMany.mockResolvedValue([]);
+
+    await saveMessages('conv-1', 'draft-1', messages);
+
+    const createManyData = mockCreateMany.mock.calls[0][0].data;
+    expect(createManyData).toHaveLength(4);
+
+    // Verify timestamps are in strictly ascending order
+    for (let i = 1; i < createManyData.length; i++) {
+      expect(createManyData[i].createdAt.getTime()).toBeGreaterThan(
+        createManyData[i - 1].createdAt.getTime()
+      );
+    }
+
+    // Verify roles alternate correctly
+    expect(createManyData[0].role).toBe('user');
+    expect(createManyData[1].role).toBe('assistant');
+    expect(createManyData[2].role).toBe('user');
+    expect(createManyData[3].role).toBe('assistant');
+  });
+
+  it('should not set createdAt when not provided by client', async () => {
+    const messages = [
+      { id: 'msg-1', role: 'user', content: 'Hello' },
+      { id: 'msg-2', role: 'assistant', content: 'Hi!' }
+    ];
+
+    mockFindMany.mockResolvedValue([]);
+
+    await saveMessages('conv-1', 'draft-1', messages);
+
+    const createManyData = mockCreateMany.mock.calls[0][0].data;
+    expect(createManyData[0].createdAt).toBeUndefined();
+    expect(createManyData[1].createdAt).toBeUndefined();
+  });
+
+  it('should separate existing messages into updates and new messages into creates', async () => {
+    // msg-1 already exists, msg-2 is new
+    mockFindMany.mockResolvedValue([{ id: 'msg-1' }]);
+
+    const messages = [
+      {
+        id: 'msg-1',
+        role: 'user',
+        content: 'Updated content',
+        createdAt: new Date('2025-01-01T10:00:00.000Z')
+      },
+      {
+        id: 'msg-2',
+        role: 'assistant',
+        content: 'New message',
+        createdAt: new Date('2025-01-01T10:00:05.000Z')
+      }
+    ];
+
+    await saveMessages('conv-1', 'draft-1', messages);
+
+    // createMany should only have the new message
+    expect(mockCreateMany).toHaveBeenCalledTimes(1);
+    const createManyData = mockCreateMany.mock.calls[0][0].data;
+    expect(createManyData).toHaveLength(1);
+    expect(createManyData[0].id).toBe('msg-2');
+    expect(createManyData[0].createdAt).toEqual(
+      new Date('2025-01-01T10:00:05.000Z')
+    );
+
+    // update should only have the existing message
+    expect(mockUpdate).toHaveBeenCalledTimes(1);
+    expect(mockUpdate).toHaveBeenCalledWith({
+      where: { id: 'msg-1' },
+      data: {
+        content: 'Updated content',
+        parts: null
+      }
+    });
+  });
+});

